import{_ as t,o as a,c as d,a6 as o}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"Design Documents Index","description":"","frontmatter":{},"headers":[],"relativePath":"design/README.md","filePath":"design/README.md","lastUpdated":1781756787000}'),i={name:"design/README.md"};function r(s,e,n,c,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="design-documents-index" tabindex="-1">Design Documents Index <a class="header-anchor" href="#design-documents-index" aria-label="Permalink to “Design Documents Index”">​</a></h1><p>This directory contains design proposals for NG. Designs are organized into three categories:</p><ul><li><strong>Active follow-ups</strong> — features that have partial implementation but remaining work</li><li><strong>Gap proposals</strong> — proposals addressing missing features for NG as a general-purpose language</li><li><strong>Archived</strong> — fully implemented designs, kept for reference</li></ul><hr><h2 id="active-follow-ups" tabindex="-1">Active Follow-Ups <a class="header-anchor" href="#active-follow-ups" aria-label="Permalink to “Active Follow-Ups”">​</a></h2><p>Designs with partial implementation, tracking remaining work:</p><ol><li><a href="./enhanced_tuples">Enhanced Tuple Types</a> — type-level tuple operations, remaining follow-ups</li><li><a href="./auto_derive_traits">Auto Traits And Derive Traits</a> — future derived formatting traits, negative auto-trait controls</li><li><a href="./ranges_slicing_pipeline">Ranges, Slicing, Fold, And Pipeline Syntax</a> — range steps, multi-sequence zip, n-ary fold</li><li><a href="./symbol_import_aliases">Symbol Import Aliases</a> — <code>import std.foo (bar as baz)</code> syntax</li></ol><hr><h2 id="gap-proposals" tabindex="-1">Gap Proposals <a class="header-anchor" href="#gap-proposals" aria-label="Permalink to “Gap Proposals”">​</a></h2><p>15 proposals addressing critical gaps in NG as a general-purpose programming language. Each has been reviewed against the existing codebase architecture and refined for implementation readiness.</p><h3 id="feasibility-ratings" tabindex="-1">Feasibility Ratings <a class="header-anchor" href="#feasibility-ratings" aria-label="Permalink to “Feasibility Ratings”">​</a></h3><table tabindex="0"><thead><tr><th>Rating</th><th>Meaning</th><th>Color</th></tr></thead><tbody><tr><td>Feasible</td><td>Can be implemented with current architecture — additive changes only</td><td>🟢</td></tr><tr><td>Moderate</td><td>Needs targeted architectural additions (new files, no rewrites)</td><td>🟡</td></tr><tr><td>Redesigned</td><td>Proposal scope changed after architecture analysis</td><td>🔴</td></tr></tbody></table><h3 id="codebase-quality-baseline" tabindex="-1">Codebase Quality Baseline <a class="header-anchor" href="#codebase-quality-baseline" aria-label="Permalink to “Codebase Quality Baseline”">​</a></h3><p>Before implementing: the existing 28,804-line codebase was audited. <strong>Verdict: no rewrite needed.</strong> The architecture (Visitor pattern, clean dependency direction), test coverage (695 tests, 3,327 assertions), and code quality (modern C++23, RAII, no circular dependencies) are solid. Three minor technical debts exist (10 global statics in typecheck.cpp, 800-line VM opcode switch, 39 repetitive numeral type patterns) but none block feature delivery. Estimated fix time: ~2 weeks total, can be done incrementally.</p><h3 id="proposals" tabindex="-1">Proposals <a class="header-anchor" href="#proposals" aria-label="Permalink to “Proposals”">​</a></h3><h4 id="p0-—-foundation-language-usability" tabindex="-1">P0 — Foundation (Language Usability) <a class="header-anchor" href="#p0-—-foundation-language-usability" aria-label="Permalink to “P0 — Foundation (Language Usability)”">​</a></h4><table tabindex="0"><thead><tr><th>#</th><th>Proposal</th><th>Effort</th><th>Feasibility</th><th>Summary</th></tr></thead><tbody><tr><td>1</td><td><a href="./gap-error-handling">Error Handling</a></td><td>1-2 wks</td><td>🟢 Feasible</td><td><code>Result&lt;T,E&gt;</code> + <code>?</code> operator. <code>?</code> desugars to existing <code>switch</code>/<code>return</code> — no new opcodes. Uses existing <code>QUERY</code> token. <code>try</code>/<code>catch</code>/<code>throw</code> deferred to Phase 2.</td></tr><tr><td>2</td><td><a href="./gap-stdlib-expansion">Standard Library Expansion</a></td><td>12 wks parallelizable</td><td>🟢 Feasible</td><td><code>HashMap</code> + <code>Hash</code> trait, <code>JSON</code>, <code>DateTime</code>, <code>math</code>, <code>regex</code>, <code>test</code>. Each module is additive (new <code>.ng</code> file + optional C++ native).</td></tr><tr><td>3</td><td><a href="./gap-lsp-ide">LSP Server and IDE Support</a></td><td>6-10 wks</td><td>🟡 Moderate</td><td>Tree-sitter grammar + DAP-compatible server. Type checker integration via new <code>DocumentCache</code> wrapper (~200 lines, no changes to existing <code>typecheck.cpp</code>).</td></tr><tr><td>4</td><td><a href="./gap-formatter">Code Formatter</a></td><td>5 wks</td><td>🟢 Feasible</td><td><code>ng fmt</code> as standalone tool. Hand-written AST pretty-printer (chosen over tree-sitter). Idempotent output, <code>--check</code>/<code>--diff</code> modes.</td></tr></tbody></table><h4 id="p1-—-ecosystem-developer-experience" tabindex="-1">P1 — Ecosystem (Developer Experience) <a class="header-anchor" href="#p1-—-ecosystem-developer-experience" aria-label="Permalink to “P1 — Ecosystem (Developer Experience)”">​</a></h4><table tabindex="0"><thead><tr><th>#</th><th>Proposal</th><th>Effort</th><th>Feasibility</th><th>Summary</th></tr></thead><tbody><tr><td>5</td><td><a href="./gap-package-manager">Package Manager</a></td><td>6 wks</td><td>🟢 Feasible</td><td>Git + path dependencies only (MVP). No registry. Sets <code>NG_MODULE_PATH</code> — leverages existing module resolution.</td></tr><tr><td>6</td><td><a href="./gap-concurrency">Concurrency: Spawn/Wait</a></td><td>2.5 wks</td><td>🔴 <strong>Redesigned</strong></td><td><strong>Replaced</strong> <code>async fun</code>/<code>await</code> (requires VM suspension — impossible without major rework) with <code>spawn</code>/<code>await</code> using C++ thread pool. Each task runs in its own VM instance — no GC thread-safety issues.</td></tr><tr><td>7</td><td><a href="./gap-debugger">Debugger (Phased)</a></td><td>13 wks total</td><td>🟡 Moderate</td><td>Phase 1: source maps + DAP skeleton. Phase 2: VM suspension + breakpoints (shared infrastructure with concurrency). Phase 3: variable inspection + stepping.</td></tr><tr><td>8</td><td><a href="./gap-c-ffi">C ABI / External FFI</a></td><td>11 wks</td><td>🟡 Moderate</td><td><code>extern fun</code>, <code>*T</code> raw pointers, <code>unsafe</code> blocks. Uses <code>libffi</code> (not assembly trampolines) for cross-platform calling convention. GC safety: Phase 1 restricts <code>*T</code> to non-GC memory.</td></tr><tr><td>9</td><td><a href="./gap-docgen">Documentation Generator</a></td><td>9 wks</td><td>🟢 Feasible</td><td><code>///</code> doc comments → HTML/Markdown. <code>ng doc --serve</code>, <code>ng doc --test</code>. Standalone tool using existing lexer + parser.</td></tr><tr><td>10</td><td><a href="./gap-build-system">Build System</a></td><td>5.5 wks</td><td>🟢 Feasible</td><td><code>ng.toml</code> project manifest, <code>ng build</code>/<code>ng run</code>, incremental compilation with dependency graph + cache invalidation.</td></tr><tr><td>11</td><td><a href="./gap-test-framework">Testing Framework</a></td><td>6.5 wks</td><td>🟢 Feasible</td><td><code>test &quot;name&quot; { }</code> as special AST node (like <code>const if</code>). Per-test VM isolation. Benchmark runner with statistical method. Property testing (<code>forAll</code>).</td></tr></tbody></table><h4 id="p2-—-advanced-features" tabindex="-1">P2 — Advanced Features <a class="header-anchor" href="#p2-—-advanced-features" aria-label="Permalink to “P2 — Advanced Features”">​</a></h4><table tabindex="0"><thead><tr><th>#</th><th>Proposal</th><th>Effort</th><th>Feasibility</th><th>Summary</th></tr></thead><tbody><tr><td>12</td><td><a href="./gap-syntax-ergonomics">Syntax Ergonomics (3 batches)</a></td><td>6-8 wks total</td><td>🟢 Feasible</td><td>Batch 1: string interpolation + <code>for</code>/<code>while</code> + <code>break</code>/<code>continue</code>. <code>for</code> reuses existing <code>LoopBindingType::LOOP_IN</code> — no new AST node. Batch 2: lambdas/closures. Batch 3: <code>match</code> expression + operator overloading.</td></tr><tr><td>13</td><td><a href="./gap-type-system-enhancements">Type System Enhancements</a></td><td>2+3+8 wks</td><td>🟡 Moderate</td><td>Sub-A: <code>never</code> type (~2w, 🟢). Sub-B: <code>impl Trait</code> return/argument position (~3w, 🟡). Sub-C: lexical borrow checker (~6-8w, reuses existing <code>movedBindings</code> infrastructure). <strong>GATs deferred indefinitely</strong> — requires lifetime system (doesn&#39;t exist).</td></tr><tr><td>14</td><td><a href="./gap-runtime-optimization">Runtime Optimization</a></td><td>6 wks</td><td>🟡 Moderate</td><td><strong>Embedding C API only</strong> (highest value, lowest risk): <code>libng</code> shared library with <code>ng_vm_create()</code>/<code>ng_vm_run_file()</code>/<code>ng_vm_call()</code>. <strong>LLVM AOT deferred to post-MVP</strong> (GC stack maps are complex). <strong>WASM via Emscripten</strong> deferred.</td></tr><tr><td>15</td><td><a href="./gap-community-infrastructure">Community Infrastructure</a></td><td>Ongoing</td><td>🟢 Feasible</td><td>Website (Hugo), playground (server-side ngi via Docker), RFC process, public roadmap. No code changes to the compiler.</td></tr></tbody></table><h3 id="key-design-decisions" tabindex="-1">Key Design Decisions <a class="header-anchor" href="#key-design-decisions" aria-label="Permalink to “Key Design Decisions”">​</a></h3><h4 id="conflicts-resolved" tabindex="-1">Conflicts Resolved <a class="header-anchor" href="#conflicts-resolved" aria-label="Permalink to “Conflicts Resolved”">​</a></h4><table tabindex="0"><thead><tr><th>Conflict</th><th>Resolution</th><th>Applies To</th></tr></thead><tbody><tr><td><code>for</code> keyword: <code>impl Trait for Type</code> vs <code>for i in range</code></td><td>Parser disambiguates by context (statement-level vs impl-level). <code>for i in range</code> reuses existing <code>LoopBindingType::LOOP_IN</code> — no new <code>ForStatement</code> AST node.</td><td>syntax-ergonomics</td></tr><tr><td><code>?</code> operator: new token vs existing <code>QUERY</code> token</td><td>Uses existing <code>QUERY</code> token (line 148 in <code>token.hpp</code>). Postfix vs ternary disambiguated by position.</td><td>error-handling</td></tr><tr><td><code>yield</code> keyword vs existing <code>YIELD_STATEMENT</code></td><td>Adds <code>KEYWORD_YIELD</code> token, reuses existing <code>YIELD_STATEMENT = 0x504</code> AST node.</td><td>concurrency</td></tr><tr><td><code>try</code>/<code>catch</code>/<code>throw</code> vs <code>Result</code> + <code>?</code></td><td>Phase 1: <code>Result</code> + <code>?</code> only (covers 95% of needs). Phase 2: <code>try</code>/<code>catch</code>/<code>throw</code> deferred until real-world usage shows the need.</td><td>error-handling</td></tr></tbody></table><h4 id="features-deferred" tabindex="-1">Features Deferred <a class="header-anchor" href="#features-deferred" aria-label="Permalink to “Features Deferred”">​</a></h4><table tabindex="0"><thead><tr><th>Feature</th><th>Reason</th><th>Revisit Condition</th></tr></thead><tbody><tr><td>GAT (Generic Associated Types)</td><td>Requires lifetime system (doesn&#39;t exist, 12+ months to build)</td><td>If/when NG gains lifetime annotations</td></tr><tr><td>Async/await state machines</td><td>VM cannot suspend; compiler cannot generate types</td><td>After VM has suspension infrastructure (post-MVP)</td></tr><tr><td>LLVM AOT compilation</td><td>GC stack maps for precise GC are very complex</td><td>When bytecode VM performance is measured as insufficient</td></tr><tr><td>JIT compilation</td><td>Too speculative; no clear use case</td><td>If benchmarks show a need</td></tr><tr><td>WASM direct compilation</td><td>Requires LLVM backend first</td><td>After LLVM AOT exists</td></tr></tbody></table><h3 id="cross-proposal-dependencies" tabindex="-1">Cross-Proposal Dependencies <a class="header-anchor" href="#cross-proposal-dependencies" aria-label="Permalink to “Cross-Proposal Dependencies”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Error Handling → Stdlib (Result-based APIs)</span></span>
<span class="line"><span>Error Handling + Stdlib → Concurrency (spawned tasks need error types)</span></span>
<span class="line"><span>Embedding API (libng) → Build System, Testing Framework, Package Manager</span></span>
<span class="line"><span>VM Suspension → Debugger Phases 2-3</span></span></code></pre></div><h3 id="effort-summary" tabindex="-1">Effort Summary <a class="header-anchor" href="#effort-summary" aria-label="Permalink to “Effort Summary”">​</a></h3><table tabindex="0"><thead><tr><th>Phase</th><th>Proposals</th><th>Total Effort</th><th>Dependencies</th></tr></thead><tbody><tr><td>Q3 2026</td><td>1-4: Error Handling, Stdlib, Formatter, Syntax Batch 1</td><td>~20 weeks</td><td>None on each other</td></tr><tr><td>Q4 2026</td><td>5-7, 9-11: Package Manager, Concurrency, LSP, Docgen, Build, Test</td><td>~42 weeks</td><td>libng extraction</td></tr><tr><td>Q1-Q2 2027</td><td>8, 12-14: C FFI, Syntax Batch 2-3, Type System, Embedding</td><td>~40 weeks</td><td>Previous phases</td></tr><tr><td>Deferred</td><td>LLVM AOT, GAT, Async/await, JIT</td><td>—</td><td>See conditions above</td></tr></tbody></table><p><strong>Estimated total: ~100 weeks of developer time (~2 developers for 1 year).</strong></p><hr><h2 id="archived-implemented-designs" tabindex="-1">Archived Implemented Designs <a class="header-anchor" href="#archived-implemented-designs" aria-label="Permalink to “Archived Implemented Designs”">​</a></h2><p>Designs whose scoped implementation has fully landed:</p><ul><li><a href="./archive/tuples">Tuple Design</a></li><li><a href="./archive/enhanced_tuples_baseline">Enhanced Tuple Implemented Baseline</a></li><li><a href="./archive/module_system">Module System Redesign Overview</a></li><li><a href="./archive/module_artifact_typechecker">Module Artifact And Typechecker Integration</a></li><li><a href="./archive/partial_move_semantics">Partial Move Semantics</a></li><li><a href="./archive/generalized_delete">Generalized <code>= delete</code> Declarations</a></li><li><a href="./archive/constant_generic_parameters">Constant Generic Parameters</a></li><li><a href="./archive/native_module_artifacts">Native Module Artifacts</a></li><li><a href="./archive/const_fun"><code>const fun</code> And Compile-Time Computation</a></li><li><a href="./archive/bytecode_module_loading">Bytecode Module Loading</a></li><li><a href="./archive/stdlib_modularization">Standard Library Modularization</a></li><li><a href="./archive/auto_derive_traits_baseline">Auto Traits And Derive Traits Implemented Baseline</a></li><li><a href="./archive/ranges_slicing_pipeline_baseline">Ranges, Slicing, Fold, And Pipeline Implemented Baseline</a></li></ul><h2 id="policy" tabindex="-1">Policy <a class="header-anchor" href="#policy" aria-label="Permalink to “Policy”">​</a></h2><ul><li>New designs should stay in this directory until their scoped implementation has landed, then move to <code>archive/</code>.</li><li>Each proposal must include: motivation, design, scope, dependencies, acceptance criteria, effort estimate, and feasibility rating.</li><li>Design decisions and conflicts should be documented in each proposal&#39;s &quot;Design Decisions&quot; section.</li></ul>`,37)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
